MUTATION_GUARD = "atcraft_reject_row_mutation"


def upgrade() -> None:
    bind = op.get_bind()
    for statement in SCHEMA_STATEMENTS:
        # psycopg treats ``%`` as a placeholder marker even when no parameters
        # are bound, so literal percents in the captured DDL (two CHECK
        # constraints use a ``'/%'`` pattern) must be doubled for the driver.
        bind.exec_driver_sql(statement.replace("%", "%%"))


def downgrade() -> None:
    # A baseline is rolled back by restoring the pre-squash backup, not by
    # replaying 58 revisions. This destructive path exists for disposable
    # databases and tests only; it leaves the extensions installed.
    bind = op.get_bind()
    for table in DOWNGRADE_TABLES:
        bind.exec_driver_sql(f'DROP TABLE IF EXISTS public."{table}" CASCADE')
    bind.exec_driver_sql(f"DROP FUNCTION IF EXISTS public.{MUTATION_GUARD}() CASCADE")
